<?php require_once __DIR__.'/config/database.php';require_once __DIR__.'/config/auth.php';require_page('audit.php');$rows=$pdo->query("SELECT a.*,COALESCE(u.name,'System') user_name FROM audit_logs a LEFT JOIN users u ON u.id=a.user_id ORDER BY a.created_at DESC LIMIT 150")->fetchAll();$page_title='Audit Trail';$page_subtitle='Independent audit role untuk melihat siapa melakukan apa, kapan, dan pada modul apa.';include __DIR__.'/includes/header.php';?><div class="notice"><div>⌘</div><div><strong>Immutable audit view</strong><span>Auditor tidak mengubah data klinis dari halaman ini. Log dicatat oleh modul saat aksi penting dilakukan.</span></div></div><div style="height:16px"></div><div class="card"><div class="card-header"><div><h3 class="section-title">System Audit Log</h3><p class="section-subtitle">150 aktivitas terakhir.</p></div></div><div class="table-wrap"><table><tr><th>Waktu</th><th>User</th><th>Aksi</th><th>Modul</th><th>Record</th><th>Deskripsi</th></tr><?php foreach($rows as $r):?><tr><td><?=h(date('d/m/Y H:i:s',strtotime($r['created_at'])))?></td><td><?=h($r['user_name'])?></td><td><span class="badge info"><?=h($r['action'])?></span></td><td><?=h($r['module'])?></td><td><?=h((string)$r['record_id'])?></td><td><?=h($r['description'])?></td></tr><?php endforeach;?></table></div></div><?php include __DIR__.'/includes/footer.php';?>